--footer-bg:#4A2E21; --footer-ink:#FFF2E2; --footer-muted:rgba(255,242,226,.68);
--shadow-sm:0 4px 14px -8px rgba(90,58,42,.35);
--shadow-md:0 20px 45px -28px rgba(90,58,42,.45), 0 6px 18px -12px rgba(90,58,42,.18);
