/* ---------- Reviews ---------- */
.reviews__summary {
  display: flex;
  align-items: center;
  gap: 16px;
  width: fit-content;
  max-width: 100%;
  margin: 0 auto clamp(22px, 3vw, 30px);
  padding: 13px 22px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 20px;
  box-shadow: var(--shadow-sm);
}

.reviews__score {
  display: flex;
  align-items: baseline;
  gap: 3px;
  padding-inline-end: 16px;
  border-inline-end: 1px solid var(--line);
}

.reviews__score strong {
  font-family: var(--font-display);
  font-size: 1.9rem;
  font-weight: 700;
  line-height: 1;
  color: var(--caramel-deep);
}

.reviews__score-out {
  font-size: 0.7rem;
  color: var(--muted);
  font-weight: 700;
}

.reviews__summary-copy p {
  font-size: 0.73rem;
  color: var(--muted);
  font-weight: 600;
  margin-top: 3px;
}

.reviews__summary-cookie {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--pink-soft);
  color: var(--pink-strong);
  margin-inline-start: 4px;
}

.reviews__summary-cookie svg {
  width: 20px;
  height: 20px;
}

.reviews__grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
}

.review-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 24px 23px 20px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 24px;
  box-shadow: var(--shadow-sm);
  transition: transform 0.35s var(--ease), box-shadow 0.35s;
}

.review-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-md);
}

.review-card__quote {
  position: absolute;
  top: 18px;
  inset-inline-end: 20px;
  color: var(--pink);
  opacity: 0.8;
}

.review-card__quote svg {
  width: 28px;
  height: 28px;
}

.review-card p {
  font-size: 0.85rem;
  line-height: 1.8;
  color: var(--ink);
  flex: 1;
  padding-top: 4px;
}

.review-card__author {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-top: 14px;
  border-top: 1px dashed var(--line);
}

.review-card__author span:last-child {
  display: flex;
  flex-direction: column;
  line-height: 1.3;
}

.review-card__author strong {
  font-size: 0.78rem;
  font-weight: 800;
}

.review-card__author small {
  font-size: 0.62rem;
  color: var(--muted);
}

/* ---------- Contact ---------- */
.contact__card {
  display: grid;
  grid-template-columns: 0.92fr 1.08fr;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 36px;
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}

.contact__info {
  position: relative;
  padding: clamp(26px, 3.6vw, 44px);
  background: var(--beige);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.contact__info::after {
  content: "";
  position: absolute;
  width: 220px;
  height: 220px;
  border-radius: 50%;
  background: var(--pink);
  filter: blur(40px);
  opacity: 0.5;
  bottom: -110px;
  inset-inline-start: -80px;
  pointer-events: none;
}

.contact__mini-kicker {
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--caramel-deep);
}

html[lang="ar"] .contact__mini-kicker {
  letter-spacing: 0;
  font-size: 0.74rem;
}

.contact__intro h3 {
  font-family: var(--font-display);
  font-size: clamp(1.45rem, 2.4vw, 1.9rem);
  line-height: 1.3;
  font-weight: 700;
  margin: 7px 0 8px;
}

