  color: var(--muted);
  font-size: 0.82rem;
  line-height: 1.8;
  max-width: 340px;
}

.contact__list {
  display: grid;
  gap: 15px;
  margin-top: 26px;
  position: relative;
  z-index: 1;
}

.contact__list li {
  display: flex;
  align-items: flex-start;
  gap: 11px;
}

.contact__icon {
  width: 38px;
  height: 38px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: var(--card);
  color: var(--caramel-deep);
  border: 1px solid var(--line);
  flex: none;
}

.contact__icon--sky { color: #4f8ea3; }
