  flex-direction: column;
  line-height: 1.4;
  padding-top: 1px;
}

.contact__list strong {
  font-size: 0.78rem;
  font-weight: 800;
}

.contact__list li span span,
.contact__list li a {
  font-size: 0.76rem;
  color: var(--muted);
}

