  transition: color 0.2s;
}

.contact__list li a:hover {
  color: var(--caramel-deep);
}

.contact__social {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: auto;
  padding-top: 26px;
  position: relative;
  z-index: 1;
}

.contact__social > span {
  font-size: 0.7rem;
  font-weight: 800;
  color: var(--muted);
}

.contact__form {
  position: relative;
  padding: clamp(26px, 3.6vw, 44px);
  display: flex;
  flex-direction: column;
  gap: 13px;
}

.contact__form h3 {
  font-family: var(--font-display);
  font-size: 1.4rem;
  font-weight: 700;
  margin-bottom: 2px;
}

.contact__form-sticker {
  position: absolute;
  top: 22px;
  inset-inline-end: 28px;
  color: var(--caramel);
  opacity: 0.5;
  transform: rotate(12deg);
}

.contact__form-sticker svg {
  width: 34px;
  height: 34px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field label {
  font-size: 0.72rem;
  font-weight: 800;
  color: var(--muted);
  padding-inline-start: 3px;
}

.field input,
.field textarea {
  width: 100%;
  padding: 11px 14px;
  border-radius: 13px;
  border: 1px solid var(--line);
  background: var(--field);
  font-size: 0.83rem;
  transition: border-color 0.25s, box-shadow 0.25s, background-color 0.4s;
  resize: vertical;
}

.field textarea {
  min-height: 96px;
}

.field input::placeholder,
.field textarea::placeholder {
  color: var(--muted);
  opacity: 0.65;
}

.field input:focus,
.field textarea:focus {
  outline: none;
  border-color: var(--caramel);
  box-shadow: 0 0 0 3px rgba(201, 139, 88, 0.18);
}

.contact__form .btn {
  margin-top: 3px;
}

.contact__form-note {
  font-size: 0.66rem;
  text-align: center;
  color: var(--muted);
}

/* ---------- Footer ---------- */
.footer {
  position: relative;
  margin-top: clamp(30px, 5vw, 54px);
  background: var(--footer-bg);
  color: var(--footer-ink);
  border-radius: 44px 44px 0 0;
  padding-top: clamp(46px, 5.5vw, 70px);
  overflow: hidden;
  transition: background-color 0.6s ease;
}

.footer::before {
  content: "";
  position: absolute;
  width: 420px;
  height: 420px;
  border-radius: 50%;
  background: rgba(232, 140, 162, 0.13);
  filter: blur(90px);
  top: -220px;
  inset-inline-end: 8%;
  pointer-events: none;
}

.footer::after {
  content: "";
  position: absolute;
  width: 360px;
  height: 360px;
  border-radius: 50%;
  background: rgba(233, 184, 114, 0.1);
  filter: blur(100px);
  bottom: -220px;
  inset-inline-start: 4%;
  pointer-events: none;
}

.footer__grid {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1.35fr 0.68fr 0.68fr 1.2fr;
  gap: clamp(24px, 4vw, 46px);
}

.brand--footer .brand__mark {
  background: rgba(255, 255, 255, 0.07);
  border-color: rgba(255, 255, 255, 0.12);
  box-shadow: none;
}

.brand--footer .brand__name {
  color: var(--footer-ink);
}

.brand--footer .brand__tag {
  color: var(--footer-muted);
}

.footer__tagline {
  color: var(--footer-muted);
  font-size: 0.82rem;
  line-height: 1.8;
  margin-top: 14px;
  max-width: 260px;
}

.socials--footer {
  margin-top: 18px;
}

.socials--footer a {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.12);
  color: var(--footer-ink);
}

.socials--footer a:hover {
  background: var(--gold);
  border-color: var(--gold);
  color: #2b1a12;
}

.footer__col {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.footer__col h3,
.footer__news h3 {
  font-family: var(--font-body);
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(255, 242, 226, 0.48);
  margin-bottom: 10px;
}

html[lang="ar"] .footer__col h3,
html[lang="ar"] .footer__news h3 {
  letter-spacing: 0;
  font-size: 0.78rem;
}

.footer__col a {
  color: var(--footer-muted);
  font-size: 0.8rem;
  padding: 3px 0;
  width: fit-content;
  transition: color 0.2s, transform 0.2s var(--ease);
}

.footer__col a:hover {
  color: var(--gold);
  transform: translateX(3px);
}

html[dir="rtl"] .footer__col a:hover {
  transform: translateX(-3px);
}

.footer__news p {
  color: var(--footer-muted);
  font-size: 0.78rem;
  line-height: 1.7;
  max-width: 280px;
}

.newsletter {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
  padding: 4px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid rgba(255, 255, 255, 0.13);
  max-width: 300px;
  transition: border-color 0.25s;
}

.newsletter:focus-within {
  border-color: var(--gold);
}

.newsletter input {
  flex: 1;
  min-width: 0;
  background: transparent;
  border: 0;
  padding: 8px 13px;
  font-size: 0.78rem;
  color: var(--footer-ink);
  outline: none;
}

.newsletter input::placeholder {
  color: var(--footer-muted);
  opacity: 0.8;
}

.newsletter button {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--gold);
  color: #2b1a12;
  flex: none;
  transition: transform 0.25s var(--ease), background-color 0.25s;
}

.newsletter button svg {
  width: 16px;
  height: 16px;
}

.newsletter button:hover {
  transform: rotate(-8deg) scale(1.05);
  background: #f7d99a;
}

.footer__hint {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 11px;
  font-size: 0.62rem;
  color: var(--footer-muted);
}

.footer__hint svg {
  width: 12px;
  height: 12px;
  color: var(--pink-strong);
  flex: none;
}

.footer__bottom {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: clamp(32px, 5vw, 52px);
  padding-block: 20px 24px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  font-size: 0.67rem;
  color: var(--footer-muted);
}

.footer__made {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.footer__made svg {
  width: 12px;
  height: 12px;
  color: var(--pink-strong);
}

.footer__scallop {
  position: absolute;
  inset-inline: 0;
  bottom: 0;
  height: 8px;
  background-image: radial-gradient(circle at 8px 12px, transparent 8px, rgba(255, 244, 228, 0.12) 9px);
  background-size: 16px 12px;
  opacity: 0.55;
  pointer-events: none;
}

