.success-modal__close {
  position: absolute;
  top: 14px;
  inset-inline-end: 14px;
}

.success-modal__art {
  position: relative;
  width: 112px;
  height: 112px;
  border-radius: 50%;
  margin: 0 auto 14px;
  display: grid;
  place-items: center;
  background: var(--pink-soft);
  color: var(--caramel-deep);
  border: 1.5px dashed var(--caramel-soft);
}

.success-modal__art > svg {
  width: 58px;
  height: 58px;
}

.success-modal__ring {
  position: absolute;
  inset: -9px;
  border-radius: 50%;
  border: 1px dashed var(--pink-strong);
  opacity: 0.65;
  animation: spin 22s linear infinite;
}

.success-modal__spark {
  position: absolute;
  border-radius: 50%;
  background: var(--gold);
}

.success-modal__spark--1 { width: 8px; height: 8px; top: 0; inset-inline-start: 12px; }
.success-modal__spark--2 { width: 6px; height: 6px; bottom: 10px; inset-inline-end: 2px; background: var(--sky); }
.success-modal__spark--3 { width: 5px; height: 5px; top: 20px; inset-inline-end: 0; background: var(--pink-strong); }

.success-modal h2 {
  font-family: var(--font-display);
  font-size: 1.65rem;
  line-height: 1.3;
  font-weight: 700;
  margin-bottom: 8px;
}

.success-modal > p {
  font-size: 0.84rem;
  line-height: 1.8;
  color: var(--muted);
  max-width: 330px;
  margin: 0 auto;
}

.success-modal__order {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin: 18px 0;
  padding: 9px 16px;
  border-radius: 12px;
  background: var(--beige);
  font-size: 0.72rem;
  color: var(--muted);
}

.success-modal__order strong {
  font-family: var(--font-body);
  font-size: 0.8rem;
  letter-spacing: 0.06em;
  color: var(--caramel-deep);
}

/* ---------- Toasts ---------- */
.toasts {
  position: fixed;
  bottom: 24px;
  inset-inline-end: 24px;
  z-index: 130;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
  max-width: calc(100% - 32px);
  pointer-events: none;
}

.toast {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  border-radius: 13px;
  background: var(--ink);
  color: var(--cream);
  font-size: 0.76rem;
  font-weight: 700;
  box-shadow: var(--shadow-lg);
  animation: toast-in 0.35s var(--ease) both;
  pointer-events: auto;
  max-width: 360px;
}

.toast svg {
  width: 15px;
  height: 15px;
  color: var(--gold);
  flex: none;
}

.toast.is-out {
  animation: toast-out 0.25s ease forwards;
}

@keyframes toast-in {
  from { opacity: 0; transform: translateY(12px) scale(0.96); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes toast-out {
  to { opacity: 0; transform: translateY(8px) scale(0.97); }
}

/* ---------- Confetti & fly-to-cart ---------- */
.confetti {
  position: fixed;
  inset: 0;
  z-index: 120;
  pointer-events: none;
  overflow: hidden;
}

.confetti-piece {
  position: absolute;
  top: -20px;
  width: 9px;
  height: 14px;
  border-radius: 2px;
  animation: confetti-fall linear forwards;
}

@keyframes confetti-fall {
  0% { transform: translate3d(0, -10px, 0) rotate(0deg); opacity: 0; }
  8% { opacity: 1; }
  100% { transform: translate3d(var(--drift, 30px), 108vh, 0) rotate(var(--rot, 540deg)); opacity: 0; }
}

.cookie-fly {
  position: fixed;
  z-index: 125;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--caramel);
  color: #4a2b1d;
  border: 2px solid var(--cream-2);
  box-shadow: var(--shadow-sm);
  pointer-events: none;
}

.cookie-fly svg {
  width: 16px;
  height: 16px;
}

/* ---------- Responsive ---------- */
@media (max-width: 1180px) {
  .nav__link {
    padding: 9px 9px;
    font-size: 0.77rem;
  }

  .mode-switch__label {
    display: none;
  }

  .mode-switch {
    padding: 4px;
  }

  .header__inner {
    gap: 12px;
  }
}

@media (max-width: 1040px) {
  .nav {
    position: absolute;
    top: calc(100% - 6px);
    inset-inline: clamp(16px, 4vw, 32px);
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 2px;
    padding: 14px;
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 24px;
    box-shadow: var(--shadow-lg);
    opacity: 0;
    visibility: hidden;
    transform: translateY(-10px);
    transition: opacity 0.3s var(--ease), transform 0.3s var(--ease), visibility 0.3s;
    z-index: 55;
  }

  .nav.is-open {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
  }

  .nav__link {
    width: 100%;
    padding: 11px 14px;
    font-size: 0.9rem;
    border-radius: 14px;
  }

  .nav__link::after {
    display: none;
  }

  .nav__link.is-active {
    background: var(--pink-soft);
  }

  .nav-toggle {
    display: grid;
  }

  .site-header.is-open {
    background: var(--header-bg);
    -webkit-backdrop-filter: blur(18px) saturate(1.3);
    backdrop-filter: blur(18px) saturate(1.3);
  }
}

@media (max-width: 980px) {
  .hero {
    min-height: auto;
    padding-top: 22px;
  }

  .hero__inner {
    grid-template-columns: 1fr;
    text-align: center;
    gap: 36px;
  }

  .hero__content {
    display: flex;
    flex-direction: column;
    align-items: center;
  }

  .hero__lead {
    margin-inline: auto;
  }

  .hero__actions,
  .hero__trust {
    justify-content: center;
  }

  .hero__visual {
    width: min(100%, 460px);
  }

  .scroll-cue {
    display: none;
  }

  .hero__sun {
    width: 72px;
    height: 72px;
    top: 5%;
    inset-inline-end: 5%;
  }

  .about__grid {
    grid-template-columns: 1fr;
    gap: 52px;
  }

  .about__media {
    width: 100%;
    max-width: 620px;
    margin-inline: auto;
  }

  .about__content {
    max-width: 640px;
    margin-inline: auto;
  }

  .addons__head,
  .offers__head {
    grid-template-columns: 1fr;
    gap: 18px;
    align-items: start;
  }

  .addons__lead {
    max-width: none;
  }

  .countdown {
    align-self: start;
  }

  .offers__grid {
    grid-template-columns: 1fr;
  }

  .offers__side {
    grid-template-columns: 1fr 1fr;
    grid-template-rows: auto;
  }

  .offer-feature {
    min-height: 340px;
  }

  .contact__card {
    grid-template-columns: 1fr;
  }

  .contact__social {
    margin-top: 22px;
  }

  .reviews__grid {
    grid-template-columns: 1fr 1fr;
  }

  .reviews__grid .review-card:last-child {
    grid-column: 1 / -1;
  }

  .footer__grid {
    grid-template-columns: 1fr 1fr;
    gap: 30px;
  }

  .footer__news {
    grid-column: 1 / -1;
  }
}

@media (max-width: 820px) {
  .product-grid {
    grid-template-columns: 1fr 1fr;
  }

  .addon-grid {
    grid-template-columns: 1fr 1fr;
  }

  .best-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 760px) {
  .header__inner {
    min-height: 74px;
  }

  .brand__mark {
    width: 42px;
    height: 42px;
  }

  .brand__cookie {
    width: 32px;
    height: 32px;
  }

  .brand__tag {
    display: none;
  }

  .brand__name {
    font-size: 1.1rem;
  }

  html[lang="ar"] .brand__name {
    font-size: 1.16rem;
  }

  .lang-btn {
    width: 40px;
    height: 40px;
    min-width: 40px;
  }

  .cart-btn {
    width: 41px;
    height: 41px;
  }

  .nav-toggle {
    width: 41px;
    height: 41px;
  }

  .hero__title {
    font-size: clamp(2.35rem, 8.6vw, 3.1rem);
  }

  .hero__visual {
    width: min(100%, 400px);
  }

  .hero__sticker--heart {
    width: 78px;
    height: 78px;
    font-size: 0.56rem;
    inset-inline-end: 6%;
  }

  .float-card--fresh {
    inset-inline-start: -2%;
  }

  .float-card--rating {
    inset-inline-end: -1%;
  }

  .about__badge {
    width: 92px;
    height: 92px;
    top: -20px;
  }

  .about__badge strong {
    font-size: 1.4rem;
  }

  .about__stat {
    inset-inline-start: 0;
    bottom: -16px;
  }

  .about__sprig {
    display: none;
  }

  .offer-feature__content {
    max-width: 68%;
  }

  .offer-feature__art {
    width: 50%;
    inset-inline-end: -11%;
  }

  .reviews__summary {
    flex-wrap: wrap;
    justify-content: center;
    text-align: center;
    padding: 13px 18px;
  }

  .reviews__score {
    border: 0;
    padding: 0;
  }

  .reviews__summary-cookie {
    display: none;
  }

  .reviews__grid {
    grid-template-columns: 1fr;
  }

  .reviews__grid .review-card:last-child {
    grid-column: auto;
  }

  .contact__social {
    flex-wrap: wrap;
  }

  .footer__bottom {
    justify-content: center;
    text-align: center;
  }

  .toasts {
    inset-inline: 16px;
    align-items: stretch;
    bottom: 16px;
  }

  .toast {
    justify-content: center;
    max-width: none;
  }
}

@media (max-width: 640px) {
  .container {
    padding-inline: 18px;
  }

  .section {
    padding-block: 62px;
  }

  .hero__actions {
    width: 100%;
    flex-direction: column;
  }

  .hero__actions .btn {
    width: 100%;
  }

  .hero__trust {
    flex-direction: column;
    gap: 8px;
  }

  .product-grid,
  .best-grid,
  .addon-grid {
    grid-template-columns: 1fr;
  }

  .offers__side {
    grid-template-columns: 1fr;
  }

  .offer-feature {
    min-height: 0;
    padding: 30px 24px;
  }

  .offer-feature__content {
    max-width: 100%;
  }

  .offer-feature__art {
    width: 78%;
    inset-inline-end: -26%;
    bottom: -32%;
    opacity: 0.24;
  }

  .offer-feature__actions {
    position: relative;
    z-index: 2;
  }

  .offer-feature__actions .btn {
    flex: 1;
  }

  .countdown {
    width: 100%;
  }

  .countdown__units {
    justify-content: center;
    width: 100%;
  }

  .countdown__unit {
    flex: 1;
  }

  .footer__grid {
    grid-template-columns: 1fr;
    gap: 28px;
  }

  .footer__news {
    grid-column: auto;
  }

  .footer__tagline {
    max-width: none;
  }

  .footer {
    border-radius: 30px 30px 0 0;
  }

  .cart-drawer {
    border-radius: 0;
  }

  .cart-drawer__head,
  .cart-drawer__body {
    padding-inline: 18px;
  }

  .cart-drawer__foot {
    padding-inline: 18px;
  }

  .about__photo {
    border-width: 6px;
  }

  .about__media::before {
    inset: 14px -10px -16px 12px;
    border-radius: 28px;
  }

  .about__badge {
    inset-inline-end: 10px;
  }

  .addons__banner {
    flex-wrap: wrap;
    text-align: start;
  }

  .addons__banner p {
    flex-basis: calc(100% - 60px);
  }

  .addons__banner .btn {
    width: 100%;
  }

  .success-modal {
    padding: 30px 20px 24px;
  }

  .cart-item {
    grid-template-columns: 58px minmax(0, 1fr) auto;
  }

  .cart-item__thumb {
    width: 58px;
    height: 58px;
  }

  .product-card__body {
    padding: 16px 17px 18px;
  }
}

@media (max-width: 420px) {
  .header__actions {
    gap: 5px;
  }

  .lang-btn__icon {
    display: none;
  }

  .lang-btn {
    width: 38px;
    height: 38px;
    min-width: 38px;
  }

  .brand {
    gap: 8px;
  }

  .brand__mark {
    width: 38px;
    height: 38px;
    border-radius: 13px;
  }

  .brand__cookie {
    width: 29px;
    height: 29px;
  }

  .brand__name {
    font-size: 0.98rem;
  }

  html[lang="ar"] .brand__name {
    font-size: 1.05rem;
  }

  .cart-btn {
    width: 38px;
    height: 38px;
  }

  .nav-toggle {
    width: 38px;
    height: 38px;
  }

  .mode-switch__track {
    width: 48px;
    height: 27px;
  }

  .mode-switch__thumb {
    width: 21px;
    height: 21px;
  }

  .mode-switch[aria-checked="true"] .mode-switch__thumb {
    transform: translateX(20px);
  }

  .hero__sticker--heart {
    display: none;
  }

  .hero__sticker--star {
    inset-inline-start: 1%;
  }

  .float-card {
    padding: 8px 10px;
    gap: 7px;
  }

  .float-card__icon {
    width: 32px;
    height: 32px;
  }

  .float-card__body strong {
    font-size: 0.7rem;
  }

  .float-card__body > span:not(.stars) {
    font-size: 0.6rem;
  }

  .float-card__score {
    font-size: 1.2rem;
  }

  .greeting {
    font-size: 0.82rem;
    padding: 7px 11px;
  }

  .foot-note {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  [data-reveal] {
    opacity: 1;
    transform: none;
  }

  .marquee__track {
    animation: none;
  }
}

@media print {
  .site-header,
  .hero__visual,
  .marquee,
  .cart-drawer,
  .drawer-overlay,
  .toasts,
  .footer {
    display: none !important;
  }

  body {
    background: #fff;
    color: #000;
  }
}

input.oldString:
.footer__scallop {
  position: absolute;
  inset-inline: 0;
  bottom: 0;
  height: 8px;
  background-image: radial-gradient(circle at 8px 12px, transparent 8px, rgba(255, 244, 228, 0.12) 9px);
  background-size: 16px 12px;
  opacity: 0.55;
  pointer-events: none;
}

files.patch:
Index: css/styles.css
===================================================================
--- css/styles.css
+++ css/styles.css
@@ -3373,5 +3373,1178 @@
   opacity: 0.55;
   pointer-events: none;
 }

+/* ---------- Cart drawer ---------- */
+.drawer-overlay,
+.modal-overlay {
+  position: fixed;
+  inset: 0;
+  background: rgba(28, 17, 12, 0.52);
+  -webkit-backdrop-filter: blur(4px);
+  backdrop-filter: blur(4px);
+  opacity: 0;
+  visibility: hidden;
+  transition: opacity 0.35s ease, visibility 0.35s ease;
+  z-index: 90;
+}

+.drawer-overlay.is-open {
+  opacity: 1;
+  visibility: visible;
+}
+
+.cart-drawer {
+  position: fixed;
+  top: 0;
+  right: 0;
+  height: 100dvh;
+  width: min(430px, 100%);
+  z-index: 95;
+  display: flex;
+  flex-direction: column;
+  background: var(--cream-2);
+  box-shadow: -30px 0 80px -40px rgba(0, 0, 0, 0.5);
+  border-top-left-radius: 26px;
+  border-bottom-left-radius: 26px;
+  transform: translateX(105%);
+  visibility: hidden;
+  transition: transform 0.45s var(--ease), visibility 0.45s, background-color 0.5s;
+  overflow: hidden;
+}
+
+.cart-drawer.is-open {
+  transform: translateX(0);
+  visibility: visible;
+}
+
+.cart-drawer__head {
+  display: flex;
+  align-items: flex-start;
+  justify-content: space-between;
+  gap: 12px;
+  padding: 22px 24px 16px;
+  border-bottom: 1px dashed var(--line);
+  flex: none;
+}
+
+.cart-drawer__kicker {
+  display: block;
+  font-size: 0.62rem;
+  font-weight: 800;
+  letter-spacing: 0.14em;
+  text-transform: uppercase;
+  color: var(--caramel-deep);
+  margin-bottom: 3px;
+}
+
+html[lang="ar"] .cart-drawer__kicker {
+  letter-spacing: 0;
+  font-size: 0.7rem;
+}
+
+.cart-drawer h2 {
+  font-family: var(--font-display);
+  font-size: 1.45rem;
+  line-height: 1.25;
+  font-weight: 700;
+}
+
+.cart-drawer__body {
+  flex: 1;
+  overflow-y: auto;
+  padding: 18px 24px;
+  display: flex;
+  flex-direction: column;
+  overscroll-behavior: contain;
+}
+
+.cart-empty {
+  flex: 1;
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  justify-content: center;
+  text-align: center;
+  gap: 7px;
+  padding: 30px 10px;
+}
+
+.cart-empty__art {
+  width: 104px;
+  height: 104px;
+  border-radius: 50%;
+  display: grid;
+  place-items: center;
+  background: var(--pink-soft);
+  border: 1.5px dashed var(--caramel-soft);
+  color: var(--caramel);
+  margin-bottom: 8px;
+}
+
+.cart-empty__art svg {
+  width: 54px;
+  height: 54px;
+}
+
+.cart-empty h3 {
+  font-family: var(--font-display);
+  font-size: 1.25rem;
+  font-weight: 700;
+  line-height: 1.3;
+}
+
+.cart-empty p {
+  font-size: 0.82rem;
+  line-height: 1.7;
+  color: var(--muted);
+  max-width: 260px;
+}
+
+.cart-empty .btn {
+  margin-top: 9px;
+}
+
+.cart-list {
+  display: flex;
+  flex-direction: column;
+  gap: 14px;
+}
+
+.cart-item {
+  display: grid;
+  grid-template-columns: 66px minmax(0, 1fr) auto;
+  gap: 11px;
+  align-items: start;
+  padding-bottom: 14px;
+  border-bottom: 1px dashed var(--line);
+  animation: cart-item-in 0.35s var(--ease) both;
+}
+
+.cart-item:last-child {
+  border-bottom: 0;
+  padding-bottom: 2px;
+}
+
+@keyframes cart-item-in {
+  from { opacity: 0; transform: translateY(8px); }
+  to { opacity: 1; transform: translateY(0); }
+}
+
+.cart-item__thumb {
+  width: 66px;
+  height: 66px;
+  border-radius: 14px;
+  overflow: hidden;
+  background: var(--beige);
+  display: grid;
+  place-items: center;
+  color: var(--caramel-deep);
+  border: 1px solid var(--line);
+}
+
+.cart-item__thumb img {
+  width: 100%;
+  height: 100%;
+  object-fit: cover;
+}
+
+.cart-item__thumb svg {
+  width: 30px;
+  height: 30px;
+}
+
+.cart-item__info {
+  min-width: 0;
+  display: flex;
+  flex-direction: column;
+  gap: 3px;
+}
+
+.cart-item__info h4 {
+  font-family: var(--font-display);
+  font-size: 0.86rem;
+  font-weight: 700;
+  line-height: 1.35;
+}
+
+.cart-item__unit {
+  font-size: 0.65rem;
+  color: var(--muted);
+}
+
+.qty {
+  display: inline-flex;
+  align-items: center;
+  gap: 5px;
+  margin-top: 3px;
+  width: fit-content;
+}
+
+.qty button {
+  width: 24px;
+  height: 24px;
+  border-radius: 7px;
+  border: 1px solid var(--line);
+  background: var(--card);
+  display: grid;
+  place-items: center;
+  transition: background-color 0.2s, color 0.2s, border-color 0.2s;
+}
+
+.qty button:hover {
+  background: var(--pink-soft);
+  border-color: var(--caramel-soft);
+}
+
+.qty button:disabled {
+  opacity: 0.4;
+  cursor: not-allowed;
+}
+
+.qty button svg {
+  width: 11px;
+  height: 11px;
+}
+
+.qty span {
+  min-width: 17px;
+  text-align: center;
+  font-size: 0.72rem;
+  font-weight: 800;
+  font-variant-numeric: tabular-nums;
+}
+
+.cart-item__end {
+  display: flex;
+  flex-direction: column;
+  align-items: flex-end;
+  gap: 7px;
+}
+
+.cart-item__total {
+  font-family: var(--font-display);
+  font-size: 0.87rem;
+  font-weight: 700;
+  color: var(--caramel-deep);
+  white-space: nowrap;
+}
+
+.remove-btn {
+  width: 26px;
+  height: 26px;
+  border-radius: 50%;
+  display: grid;
+  place-items: center;
+  color: var(--muted);
+  transition: color 0.2s, background-color 0.2s;
+}
+
+.remove-btn:hover {
+  color: #c25a5a;
+  background: var(--pink-soft);
+}
+
+.remove-btn svg {
+  width: 13px;
+  height: 13px;
+}
+
+.cart-drawer__foot {
