function flyToCart(source){
 if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;
 const r = source.getBoundingClientRect(); const target = cartBtn.getBoundingClientRect();
 const fly = document.createElement('span'); fly.className='cookie-fly'; fly.innerHTML='<svg><use href="#i-cookie"/></svg>';
 fly.style.left = `${r.left + r.width/2 - 13}px`; fly.style.top = `${r.top + r.height/2 - 13}px`;
 document.body.appendChild(fly);
 const dx = target.left+target.width/2 - (r.left+r.width/2);
 const dy = target.top+target.height/2 - (r.top+r.height/2);
 const anim = fly.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${dx*0.6}px, ${dy*0.6-50}px) scale(1.15)`, opacity:1, offset:.55},{transform:`translate(${dx}px, ${dy}px) scale(.45)`,opacity:.2}], {duration:700, easing:'cubic-bezier(.3,.7,.4,1)'});
 anim.onfinish = ()=> fly.remove();
 setTimeout(()=>fly.remove(), 1200);
 setTimeout(()=> bumpCart(), 600);
}
```
